@IsTest
private class BestDiscountCounterTests {
    @TestSetup
    static void setup() {
        List<Discount__c> discounts = new List<Discount__c>();
        discounts.add(DiscountBuilder.create()
                .withName('Test Discount 2')
                .withDiscountType('Time-Bound')
                .withValueType('Amount')
                .withDiscountValue(50)
                .withStartDate(System.today().addDays(-1))
                .withEndDate(System.today().addDays(1))
                .withIsActive(true)
                .build());
        insert discounts;

        Product2 product1 = ProductBuilder.create()
                .withName('Test Product 1')
                .withIsActive(true)
                .withProductCode('TP1')
                .withDescription('Test Product 1 Description')
                .build();
        insert product1;

        Id priceBookId = Test.getStandardPricebookId();

        PricebookEntry pbe1 = PricebookEntryBuilder.create()
                .withPricebook2Id(priceBookId)
                .withProduct2Id(product1.Id)
                .withUnitPrice(100.0)
                .withIsActive(true)
                .build();
        insert pbe1;

        Account account = AccountBuilder.create()
                .withName('Test Account')
                .build();
        insert account;

        Order order = OrderBuilder.create()
                .withAccountId(account.Id)
                .withEffectiveDate(System.today())
                .withPricebook2Id(priceBookId)
                .withStatus('Draft')
                .build();
        insert order;

        OrderItem orderItem = OrderItemBuilder.create()
                .withOrderId(order.Id)
                .withPricebookEntryId(pbe1.Id)
                .withQuantity(10)
                .withUnitPrice(100.0)
                .build();
        insert orderItem;
    }

    @IsTest
    static void testGetMatchingDiscountWithPercentage() {
        List<Discount__c> discounts = [SELECT Id, Name, Discount_Type__c, Value_Type__c, Discount_Value__c FROM Discount__c WHERE Is_Active__c = TRUE];
        Order order = [SELECT Id, TotalAmount FROM Order WHERE Status = :ConstUtil.ORDER_STATUS_DRAFT LIMIT 1];
        DiscountSettings settings = new DiscountSettings(ConstUtil.DISCOUNT_STRATEGY_HIGHEST, 50.0);

        Test.startTest();
        Discount__c bestDiscount = BestDiscountCounter.getMatchingDiscount(discounts, settings, order);
        Test.stopTest();

        System.assertNotEquals(null, bestDiscount, 'Best discount should not be null');
        System.assertEquals('Test Discount 1', bestDiscount.Name, 'Best discount should be the one with the highest percentage');
    }
}

